create table public.account_deletions (
  user_id uuid not null,
  requested_at timestamp with time zone default now() not null,
  delete_after timestamp with time zone default (now() + '7 days'::interval) not null,
  cancelled_at timestamp with time zone,
  last_error text,
  last_attempt_at timestamp with time zone,
  constraint account_deletions_pkey PRIMARY KEY (user_id),
  constraint account_deletions_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint account_deletions_check CHECK ((delete_after > requested_at)),
  constraint account_deletions_last_error_check CHECK ((char_length(last_error) <= 1000))
);

CREATE INDEX account_deletions_due ON public.account_deletions USING btree (delete_after) WHERE (cancelled_at IS NULL);

alter table public.account_deletions enable row level security;

grant delete, insert, maintain, references, select, trigger, truncate, update on table public.account_deletions to service_role;
